reqs = ["SYS-101", "SYS-102", "SYS-103", "SYS-104"]
tests = {"IT-01": ["SYS-101"], "IT-02": ["SYS-102"], "IT-03": ["SYS-102", "SYS-103"]}
results = {"IT-01": "pass", "IT-02": "fail", "IT-03": "pass"}
for r in reqs:
    tcs = [t for t, rs in tests.items() if r in rs]
    if not tcs:
        print(r, "시험 없음")
    elif any(results.get(t) != "pass" for t in tcs):
        print(r, "실패:", [t for t in tcs if results.get(t) != "pass"])
    else:
        print(r, "통과", tcs)
# SYS-101 통과 ['IT-01']
# SYS-102 실패: ['IT-02']
# SYS-103 통과 ['IT-03']
# SYS-104 시험 없음

b1 = {"hpvc_os": "3.4.0", "zone_front": "1.8.2", "zone_rear": "1.8.2", "ivi": "2.1.0", "adas": "0.9.7"}
b2 = {"hpvc_os": "3.4.1", "zone_front": "1.8.2", "zone_rear": "1.9.0", "ivi": "2.1.0", "adas": "0.9.7"}
suite = {"hpvc_os": ["부팅", "OTA 설치"], "zone_rear": ["후방 램프", "트렁크"], "ivi": ["미디어"]}
changed = [k for k in b1 if b1[k] != b2[k]]
print("바뀐 부품:", changed)
print("다시 돌릴 시험:", sorted({t for c in changed for t in suite.get(c, [])}))
# 바뀐 부품: ['hpvc_os', 'zone_rear']
# 다시 돌릴 시험: ['OTA 설치', '부팅', '트렁크', '후방 램프']

deps = {"adas_app": ["vehicle_api", "camera_fw"], "ivi_app": ["vehicle_api"],
        "vehicle_api": ["zone_ctrl_fw"], "ota_agent": ["vehicle_api", "bootloader"],
        "camera_fw": [], "zone_ctrl_fw": [], "bootloader": []}
users = {}
for a, bs in deps.items():
    for b in bs:
        users.setdefault(b, []).append(a)
def impacted(changed):
    seen, todo = set(), [changed]
    while todo:
        for u in users.get(todo.pop(), []):
            if u not in seen:
                seen.add(u)
                todo.append(u)
    return sorted(seen)
print("zone_ctrl_fw 바뀜 ->", impacted("zone_ctrl_fw"))
print("camera_fw 바뀜 ->", impacted("camera_fw"))
# zone_ctrl_fw 바뀜 -> ['adas_app', 'ivi_app', 'ota_agent', 'vehicle_api']
# camera_fw 바뀜 -> ['adas_app']
